CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, email text NOT NULL UNIQUE, name text, role text NOT NULL DEFAULT 'CUSTOMER' CHECK (role IN ('CUSTOMER','STAFF','ADMIN')), password_hash text, password_salt text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS admin_sessions_user_id_idx ON admin_sessions(user_id); CREATE INDEX IF NOT EXISTS admin_sessions_expires_at_idx ON admin_sessions(expires_at);
CREATE TABLE IF NOT EXISTS categories (id text PRIMARY KEY, name text NOT NULL, slug text NOT NULL UNIQUE, description text, image_url text, sort_order integer NOT NULL DEFAULT 0, is_published boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS collections (id text PRIMARY KEY, name text NOT NULL, slug text NOT NULL UNIQUE, description text, hero_image_url text, is_published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id text PRIMARY KEY, category_id text REFERENCES categories(id) ON DELETE SET NULL, name text NOT NULL, slug text NOT NULL UNIQUE, description text, status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','PUBLISHED','ARCHIVED')), featured boolean NOT NULL DEFAULT false, low_stock_threshold integer NOT NULL DEFAULT 8 CHECK (low_stock_threshold >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS products_category_id_idx ON products(category_id); CREATE INDEX IF NOT EXISTS products_status_idx ON products(status);
CREATE TABLE IF NOT EXISTS collection_products (collection_id text NOT NULL REFERENCES collections(id) ON DELETE CASCADE, product_id text NOT NULL REFERENCES products(id) ON DELETE CASCADE, sort_order integer NOT NULL DEFAULT 0, PRIMARY KEY(collection_id, product_id));
CREATE TABLE IF NOT EXISTS product_variants (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products(id) ON DELETE CASCADE, title text NOT NULL, sku text NOT NULL UNIQUE, price_cents integer NOT NULL CHECK (price_cents >= 0), compare_at_price_cents integer, cost_cents integer, stock integer NOT NULL DEFAULT 0 CHECK (stock >= 0), attributes_json jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS product_variants_product_id_idx ON product_variants(product_id);
CREATE TABLE IF NOT EXISTS product_images (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products(id) ON DELETE CASCADE, variant_id text REFERENCES product_variants(id) ON DELETE SET NULL, url text NOT NULL, alt_text text, position integer NOT NULL DEFAULT 0, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS product_images_product_id_idx ON product_images(product_id);
CREATE UNIQUE INDEX IF NOT EXISTS product_primary_image_unique ON product_images(product_id) WHERE is_primary;
CREATE TABLE IF NOT EXISTS inventory_movements (id text PRIMARY KEY, variant_id text NOT NULL REFERENCES product_variants(id) ON DELETE CASCADE, quantity integer NOT NULL, type text NOT NULL CHECK (type IN ('PURCHASE','SALE','RETURN','REFUND','CORRECTION','LOSS','DAMAGE','MANUAL')), reason text NOT NULL, actor_id text REFERENCES users(id) ON DELETE SET NULL, order_id text, reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS inventory_movements_variant_id_idx ON inventory_movements(variant_id);
CREATE TABLE IF NOT EXISTS addresses (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, label text, first_name text NOT NULL, last_name text NOT NULL, line1 text NOT NULL, line2 text, city text NOT NULL, postal_code text NOT NULL, country text NOT NULL, phone text, is_default boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS carts (id text PRIMARY KEY, user_id text REFERENCES users(id) ON DELETE CASCADE, session_key text, currency text NOT NULL DEFAULT 'EUR', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cart_items (id text PRIMARY KEY, cart_id text NOT NULL REFERENCES carts(id) ON DELETE CASCADE, variant_id text NOT NULL REFERENCES product_variants(id) ON DELETE CASCADE, quantity integer NOT NULL CHECK (quantity > 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cart_id, variant_id));
CREATE TABLE IF NOT EXISTS orders (id text PRIMARY KEY, order_number text NOT NULL UNIQUE, user_id text REFERENCES users(id) ON DELETE SET NULL, email text NOT NULL, status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','AWAITING_PAYMENT','PAID','PROCESSING','SHIPPED','DELIVERED','CANCELLED','REFUNDED')), currency text NOT NULL DEFAULT 'EUR', subtotal_cents integer NOT NULL, discount_cents integer NOT NULL DEFAULT 0, shipping_cents integer NOT NULL DEFAULT 0, tax_cents integer NOT NULL DEFAULT 0, total_cents integer NOT NULL, shipping_address_json jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_user_id_idx ON orders(user_id);
CREATE TABLE IF NOT EXISTS order_items (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id) ON DELETE CASCADE, variant_id text REFERENCES product_variants(id) ON DELETE SET NULL, title_snapshot text NOT NULL, sku_snapshot text, image_url_snapshot text, unit_price_cents integer NOT NULL, quantity integer NOT NULL CHECK (quantity > 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id) ON DELETE CASCADE, provider text NOT NULL, provider_reference text, status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','AUTHORIZED','PAID','FAILED','REFUNDED')), amount_cents integer NOT NULL, currency text NOT NULL, idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS discounts (id text PRIMARY KEY, code text NOT NULL UNIQUE, type text NOT NULL CHECK (type IN ('PERCENTAGE','FIXED')), value integer NOT NULL, minimum_cents integer, starts_at timestamptz, ends_at timestamptz, max_uses integer, uses_count integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses (id text PRIMARY KEY, category text NOT NULL, description text NOT NULL, amount_cents integer NOT NULL, supplier text, receipt_url text, incurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id text PRIMARY KEY, actor_id text REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, resource_type text NOT NULL, resource_id text, before_json jsonb, after_json jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS store_settings (id text PRIMARY KEY, store_name text NOT NULL, currency text NOT NULL DEFAULT 'EUR', logo_url text, legal_text text, tax_rate_basis_points integer NOT NULL DEFAULT 0, default_low_stock_threshold integer NOT NULL DEFAULT 8, socials_json jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());

